INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2708498, 377196, 44086, '<td valign="top">Great angle and image. A little soft though 6</td>', 'Great angle and image. A little soft though 6', '2006-08-09 01:22:10.000000', NULL, 1),
(2708500, 375506, 41008, '<td valign="top">great look</td>', 'great look', '2006-08-09 01:22:19.000000', NULL, 1),
(2708502, 377306, 53316, '<td valign="top">Doesn''t say transportation to me except for the title.  BUT I must say, this is a delightful image.  I looked over all the thumbnails and this was the first one that jumped out at me.  I have had two sweet white mice as pets and hold a special place in my heart for them.  I love... LOVE what you have done with the lighting.  Very unique, and I think it captures the elegance that is hidden within this small creature.  I like how so much of the photo is dark yet you still captured very fine details.  I don''t think I''m voting in this challenge, and I don''t know what I would vote your image, but I do want to thank you for such a wonderful shot.</td>', 'Doesn''t say transportation to me except for the title.  BUT I must say, this is a delightful image.  I looked over all the thumbnails and this was the first one that jumped out at me.  I have had two sweet white mice as pets and hold a special place in my heart for them.  I love... LOVE what you have done with the lighting.  Very unique, and I think it captures the elegance that is hidden within this small creature.  I like how so much of the photo is dark yet you still captured very fine details.  I don''t think I''m voting in this challenge, and I don''t know what I would vote your image, but I do want to thank you for such a wonderful shot.', '2006-08-09 01:22:27.000000', NULL, 1),
(2708507, 376535, 41008, '<td valign="top">very interesting photo, very disorienting and that''s what I like about it</td>', 'very interesting photo, very disorienting and that''s what I like about it', '2006-08-09 01:23:00.000000', NULL, 1),
