(2712396, 376052, 58785, '<td valign="top">If he would take the backpack off, and if he would look like actually pulling the car... it would be a lot better... 6</td>', 'If he would take the backpack off, and if he would look like actually pulling the car... it would be a lot better... 6', '2006-08-09 21:15:19.000000', NULL, 1),
(2712397, 376049, 52854, '<td valign="top">Too blurry.</td>', 'Too blurry.', '2006-08-09 21:15:20.000000', NULL, 1),
(2712400, 377240, 58785, '<td valign="top">Can''t see much... Very small image :( 4</td>', 'Can''t see much... Very small image :( 4', '2006-08-09 21:15:45.000000', NULL, 1),
(2712403, 374633, 58785, '<td valign="top">Your afford stays a little... well, little. I wish you would make this photo little more attractive by choosing a better ground, and playing with the colors a bit... I don''t know. I will say 4, sorry.</td>', 'Your afford stays a little... well, little. I wish you would make this photo little more attractive by choosing a better ground, and playing with the colors a bit... I don''t know. I will say 4, sorry.', '2006-08-09 21:18:11.000000', NULL, 1),
