(2712923, 376514, 63601, '<td valign="top">I like the cars in the reflections.</td>', 'I like the cars in the reflections.', '2006-08-09 23:07:16.000000', NULL, 1),
(2712927, 377254, 60240, '<td valign="top">I love this picture.  I have a fondness for these vehicles.  Also like ailing buildings in landscapes.  That said, this could have scored higher from me if it was in fact more of a landscape.  Either include the hill above or don''t.  Unless of course there were more distracting element outside the frame.</td>', 'I love this picture.  I have a fondness for these vehicles.  Also like ailing buildings in landscapes.  That said, this could have scored higher from me if it was in fact more of a landscape.  Either include the hill above or don''t.  Unless of course there were more distracting element outside the frame.', '2006-08-09 23:08:39.000000', NULL, 1),
(2712929, 377460, 60240, '<td valign="top">Ominous.</td>', 'Ominous.', '2006-08-09 23:08:56.000000', NULL, 1),
(2712932, 375962, 63601, '<td valign="top">The line of the wires and box cars really draw me in to this photo. The warm tones and clear sky remind of the Canadian prairie which I associate with trains for some reason. The highlights on the right two cars are a bit distracting for me, but otherwise this is excellent.</td>', 'The line of the wires and box cars really draw me in to this photo. The warm tones and clear sky remind of the Canadian prairie which I associate with trains for some reason. The highlights on the right two cars are a bit distracting for me, but otherwise this is excellent.', '2006-08-09 23:10:05.000000', NULL, 1),
