(2714767, 374946, 52500, '<td valign="top">Nice angle.  He''s almost right on top of you!</td>', 'Nice angle.  He''s almost right on top of you!', '2006-08-10 14:02:17.000000', NULL, 1),
(2714776, 375505, 52500, '<td valign="top">This is great.  I love the "working on a boat while sitting in a boat" double whammy.  Great color and composition.  I really like the reflection as well.</td>', 'This is great.  I love the "working on a boat while sitting in a boat" double whammy.  Great color and composition.  I really like the reflection as well.', '2006-08-10 14:04:11.000000', NULL, 1),
