(2718860, 376656, 62006, '<td valign="top">Beautiful colors</td>', 'Beautiful colors', '2006-08-11 18:27:33.000000', NULL, 1),
(2718871, 376701, 42792, '<td valign="top">By itself, this is an awesome shot!  Just find it''s more about lines &amp; lights than the idea of transportation - at least the way the image jumps out at me at first glance (the transportation bit seeps in as an afterthought).  Still, love everything about it - so 8!</td>', 'By itself, this is an awesome shot!  Just find it''s more about lines & lights than the idea of transportation - at least the way the image jumps out at me at first glance (the transportation bit seeps in as an afterthought).  Still, love everything about it - so 8!', '2006-08-11 18:30:05.000000', NULL, 1),
