(2720179, 376482, 27524, '<td valign="top">Love the colors and focus but composition feel bit too straight for me. I would try different angles.</td>', 'Love the colors and focus but composition feel bit too straight for me. I would try different angles.', '2006-08-12 10:02:02.000000', NULL, 1),
(2720181, 374705, 45919, '<td valign="top">Very nice...   Captures the speed of the car because of the motion blur as well.  Great title to the shot.</td>', 'Very nice...   Captures the speed of the car because of the motion blur as well.  Great title to the shot.', '2006-08-12 10:02:35.000000', NULL, 1),
(2720185, 377318, 45919, '<td valign="top">Very good shot of the 500 landing on unsatble rock and capturing enough of the countryside to emphasize the photo''s title, well done.</td>', 'Very good shot of the 500 landing on unsatble rock and capturing enough of the countryside to emphasize the photo''s title, well done.', '2006-08-12 10:04:06.000000', NULL, 1),
(2720186, 376479, 63104, '<td valign="top">I''m 27 % through rating this challenge, and without a doubt, this is the best shot thus far by a long way. Love the bold colours, and this this would have been a great entry in the Fire challenge as well. Well done.</td>', 'I''m 27 % through rating this challenge, and without a doubt, this is the best shot thus far by a long way. Love the bold colours, and this this would have been a great entry in the Fire challenge as well. Well done.', '2006-08-12 10:04:23.000000', NULL, 1),
(2720188, 376557, 27524, '<td valign="top">Real mystery photo...need a bit closer look to understand whats going on. I like your idea is original and minimal lights make it interesting. Only remark that its bit tight cropped at the back of the car.</td>', 'Real mystery photo...need a bit closer look to understand whats going on. I like your idea is original and minimal lights make it interesting. Only remark that its bit tight cropped at the back of the car.', '2006-08-12 10:04:44.000000', NULL, 1),
