(2720236, 377618, 27524, '<td valign="top">Its interesting capture. For this one i defenetly would go for B&amp;w image. Also if you possibly could capture it bit later when the purple object are not in photo It would be already lot of improvement.</td>', 'Its interesting capture. For this one i defenetly would go for B&w image. Also if you possibly could capture it bit later when the purple object are not in photo It would be already lot of improvement.', '2006-08-12 10:21:43.000000', NULL, 1),
(2720238, 375043, 45919, '<td valign="top">I love the name of the photo and a good representation of the challenge, well done.</td>', 'I love the name of the photo and a good representation of the challenge, well done.', '2006-08-12 10:21:55.000000', NULL, 1),
(2720239, 375848, 46330, '<td valign="top">Well done shot.  The mood perfectly fits the subject matter.  I would consider experimenting with some slightly tighter crops, but it may end up being just different and not necessarily better.</td>', 'Well done shot.  The mood perfectly fits the subject matter.  I would consider experimenting with some slightly tighter crops, but it may end up being just different and not necessarily better.', '2006-08-12 10:22:10.000000', NULL, 1),
