(2720244, 377608, 27524, '<td valign="top">Its nice artistic b&amp;w image but missing some points. Its bit overexposed so bottom part is too bright and loosing detail. There is bit too much empty space above...would prefere more panoramic crop.</td>', 'Its nice artistic b&w image but missing some points. Its bit overexposed so bottom part is too bright and loosing detail. There is bit too much empty space above...would prefere more panoramic crop.', '2006-08-12 10:25:29.000000', NULL, 1),
(2720245, 375506, 46330, '<td valign="top">Nice capture.  Well composed, and the muted colors seem very appropriate to the subject matter.  My only complaint would be the out of focus wire in the foreground.</td>', 'Nice capture.  Well composed, and the muted colors seem very appropriate to the subject matter.  My only complaint would be the out of focus wire in the foreground.', '2006-08-12 10:25:34.000000', NULL, 1),
(2720246, 375296, 45919, '<td valign="top">Very nice shot.</td>', 'Very nice shot.', '2006-08-12 10:26:57.000000', NULL, 1),
(2720247, 377002, 27524, '<td valign="top">Generaly good image...like your angle and composition also sepia work here real nice. The major minus is that it feel not enough in focus.</td>', 'Generaly good image...like your angle and composition also sepia work here real nice. The major minus is that it feel not enough in focus.', '2006-08-12 10:27:22.000000', NULL, 1),
(2720252, 375383, 27524, '<td valign="top">Great object and clolors. Its taken in too bright sun and causing too high contrast.</td>', 'Great object and clolors. Its taken in too bright sun and causing too high contrast.', '2006-08-12 10:31:20.000000', NULL, 1),
(2720263, 374860, 61679, '<td valign="top">Back to comment.  I''m afraid your score will suffer on this image because the subject matter is not the strongest for a Transportation challenge.  Technically this photo is pretty well done.  The headset does blend into the background a bit at the bottom of the image and the bright spot at the bottom left is distracting.  You might want to try cropping the bottom part of the image until the bright spot dissappears.</td>', 'Back to comment.  I''m afraid your score will suffer on this image because the subject matter is not the strongest for a Transportation challenge.  Technically this photo is pretty well done.  The headset does blend into the background a bit at the bottom of the image and the bright spot at the bottom left is distracting.  You might want to try cropping the bottom part of the image until the bright spot dissappears.', '2006-08-12 10:45:02.000000', NULL, 1),
(2720266, 376529, 61679, '<td valign="top">I don''t think you could have chosen tougher lighting conditions to capture this image under.  Although the fake rainbow and the glare off the tail wing are interesting to some degree, this image is hard on the eyes and not very engaging to look at.</td>', 'I don''t think you could have chosen tougher lighting conditions to capture this image under.  Although the fake rainbow and the glare off the tail wing are interesting to some degree, this image is hard on the eyes and not very engaging to look at.', '2006-08-12 10:47:41.000000', NULL, 1),
(2720268, 377312, 62006, '<td valign="top">This is pretty cool. Like the fog and positioning of the bikes.</td>', 'This is pretty cool. Like the fog and positioning of the bikes.', '2006-08-12 10:48:57.000000', NULL, 1),
(2720272, 375043, 63104, '<td valign="top">very nice, almost zen like in its motion through stillness :)</td>', 'very nice, almost zen like in its motion through stillness :)', '2006-08-12 10:50:04.000000', NULL, 1),
(2720276, 376640, 62006, '<td valign="top">Nice photo. I like the grasses in the foreground</td>', 'Nice photo. I like the grasses in the foreground', '2006-08-12 10:51:03.000000', NULL, 1),
(2720278, 375327, 62006, '<td valign="top">I really like this shot. Beautiful colors and composition. After voting on all and coming back to this one, I had to bump my sscore up. Very creative view. Good Luck</td>', 'I really like this shot. Beautiful colors and composition. After voting on all and coming back to this one, I had to bump my sscore up. Very creative view. Good Luck', '2006-08-12 10:53:05.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2720282, 374594, 61679, '<td valign="top">This old Allis-Chalmers has a lot of charm and is a good subject for this challenge.  There are a few technical things about this image that are going to hurt your score.  First, the b&amp;w conversion is not very well done.  There are not a whole lot of gray tones in this image, which is causing the tractor to get lost in the background.  You might want to check out the tutorial section, as fotomann has written a very nice piece on b&amp;w conversions.  Second, the straight on angle you used to capture this image is not very interesting and give the picture a snapshot like appearance.  Thirdly, the image could use a little bit of sharpening to help the details of the tractor to pop out more.</td>', 'This old Allis-Chalmers has a lot of charm and is a good subject for this challenge.  There are a few technical things about this image that are going to hurt your score.  First, the b&w conversion is not very well done.  There are not a whole lot of gray tones in this image, which is causing the tractor to get lost in the background.  You might want to check out the tutorial section, as fotomann has written a very nice piece on b&w conversions.  Second, the straight on angle you used to capture this image is not very interesting and give the picture a snapshot like appearance.  Thirdly, the image could use a little bit of sharpening to help the details of the tractor to pop out more.', '2006-08-12 10:55:06.000000', NULL, 1),
(2720283, 376692, 26464, '<td valign="top">nice, could use a bit more contrast for -punch-</td>', 'nice, could use a bit more contrast for -punch-', '2006-08-12 10:55:15.000000', NULL, 1),
(2720284, 376479, 62006, '<td valign="top">Good capture. Would like to see more detail in the flame but overall a great shot. Would be great in the upcoming challenge. Good luck.</td>', 'Good capture. Would like to see more detail in the flame but overall a great shot. Would be great in the upcoming challenge. Good luck.', '2006-08-12 10:55:29.000000', NULL, 1),
(2720285, 374701, 26464, '<td valign="top">nice urban study</td>', 'nice urban study', '2006-08-12 10:55:57.000000', NULL, 1),
(2720286, 377467, 61679, '<td valign="top">To be honest, I like the subject matte of this image a lot but I totally hate the lens glare.</td>', 'To be honest, I like the subject matte of this image a lot but I totally hate the lens glare.', '2006-08-12 10:56:15.000000', NULL, 1),
(2720288, 374268, 63104, '<td valign="top">great capture</td>', 'great capture', '2006-08-12 10:56:34.000000', NULL, 1),
(2720289, 374971, 26464, '<td valign="top">nice, not sure i like the ''colour splash'' around the wheel and near top?</td>', 'nice, not sure i like the ''colour splash'' around the wheel and near top?', '2006-08-12 10:56:41.000000', NULL, 1),
(2720292, 375993, 26464, '<td valign="top">if thats what you see, you shouldn''t be driving.. lol 6</td>', 'if thats what you see, you shouldn''t be driving.. lol 6', '2006-08-12 10:57:55.000000', NULL, 1),
(2720293, 377373, 62006, '<td valign="top">Nice shot. Processing makes it look almost like a painting. Great angle to shoot from and the positioning of the tractor works well. Good luck.</td>', 'Nice shot. Processing makes it look almost like a painting. Great angle to shoot from and the positioning of the tractor works well. Good luck.', '2006-08-12 10:57:58.000000', NULL, 1),
(2720294, 376518, 61679, '<td valign="top">Back to comment.  You made a minor mistake with this image by focusing on the mirror instead of the object in the mirror.  Since the object in the mirror is the main subject of the photo, being out of focus is going to hurt your score considerably.</td>', 'Back to comment.  You made a minor mistake with this image by focusing on the mirror instead of the object in the mirror.  Since the object in the mirror is the main subject of the photo, being out of focus is going to hurt your score considerably.', '2006-08-12 10:58:05.000000', NULL, 1),
(2720295, 376522, 61679, '<td valign="top">Back to comment.  The concept of your entry is an interesting take on the challenge topic.  This image has a few technical issues that I think are going to hurt your score.  First, the uneven light on the girl is very unflattering.  You could have used a fill flash (Something I seldom remember to do myself) or a reflector to help fill in the shadows.  Second, the background doesn''t really convey the theme of your title.  It is very busy and a little harsh looking.  I''ve just started to look at the background of my images before I shoot as much as I do the main subject.  Even so, I still get images that become very average looking because of the background.  You had a good idea and just need a little work to make it happen.</td>', 'Back to comment.  The concept of your entry is an interesting take on the challenge topic.  This image has a few technical issues that I think are going to hurt your score.  First, the uneven light on the girl is very unflattering.  You could have used a fill flash (Something I seldom remember to do myself) or a reflector to help fill in the shadows.  Second, the background doesn''t really convey the theme of your title.  It is very busy and a little harsh looking.  I''ve just started to look at the background of my images before I shoot as much as I do the main subject.  Even so, I still get images that become very average looking because of the background.  You had a good idea and just need a little work to make it happen.', '2006-08-12 10:58:16.000000', NULL, 1),
(2720298, 376656, 26464, '<td valign="top">wow, now this is nice... and i suppose it''s a form of transportation, bug you''re hugging the line... 7</td>', 'wow, now this is nice... and i suppose it''s a form of transportation, bug you''re hugging the line... 7', '2006-08-12 10:59:20.000000', NULL, 1),
(2720304, 377114, 26464, '<td valign="top">nice... hope the dog was rescued...</td>', 'nice... hope the dog was rescued...', '2006-08-12 11:01:21.000000', NULL, 1),
(2720306, 375550, 26464, '<td valign="top">nice processing</td>', 'nice processing', '2006-08-12 11:01:41.000000', NULL, 1),
