(2721582, 377527, 44086, '<td valign="top">This looks like it was overexposed and then desaturated to make it work. It''s just harsh to look at.</td>', 'This looks like it was overexposed and then desaturated to make it work. It''s just harsh to look at.', '2006-08-13 00:10:08.000000', NULL, 1),
(2721587, 376692, 44086, '<td valign="top">Contrast too low. Correct with levels, curves or brightness/contrast tools.</td>', 'Contrast too low. Correct with levels, curves or brightness/contrast tools.', '2006-08-13 00:10:52.000000', NULL, 1),
