(2721756, 376551, 45475, '<td valign="top">Awesome capture. Very well controlled. Love the heat displacement from the engines. Great work.</td>', 'Awesome capture. Very well controlled. Love the heat displacement from the engines. Great work.', '2006-08-13 01:55:02.000000', NULL, 1),
(2721764, 377452, 45475, '<td valign="top">Good tones, the shadows are severly clipped, but I suspect this was done intentionally. Great perspective and strong composition/subject matter. I give it a 10.</td>', 'Good tones, the shadows are severly clipped, but I suspect this was done intentionally. Great perspective and strong composition/subject matter. I give it a 10.', '2006-08-13 01:57:41.000000', NULL, 1),
