(2721804, 377571, 45475, '<td valign="top">This is wonderful! Did you selective desat or was that the natural colour of the sky? Well spotted and taken all the same. 8</td>', 'This is wonderful! Did you selective desat or was that the natural colour of the sky? Well spotted and taken all the same. 8', '2006-08-13 02:10:45.000000', NULL, 1),
(2721811, 376629, 45475, '<td valign="top">Beautiful work! Not a lot to critique here other than maybe the contrast or sharpening feels a bit strong. But that could be just me. 8</td>', 'Beautiful work! Not a lot to critique here other than maybe the contrast or sharpening feels a bit strong. But that could be just me. 8', '2006-08-13 02:13:14.000000', NULL, 1),
(2721814, 374772, 45475, '<td valign="top">Great job. Just wish it was bigger. 8</td>', 'Great job. Just wish it was bigger. 8', '2006-08-13 02:13:40.000000', NULL, 1),
(2721888, 373995, 60173, '<td valign="top">You''re too far away for there to be any real focal point. We see a guy stretching, but just barely. In these times I think a lot of people want to see the price of gas too, heh. As I see it, this is just a point and shoot photo made black and white in attempts to make it look better. There needs to be a tighter crop or something to give the audience something to look at.</td>', 'You''re too far away for there to be any real focal point. We see a guy stretching, but just barely. In these times I think a lot of people want to see the price of gas too, heh. As I see it, this is just a point and shoot photo made black and white in attempts to make it look better. There needs to be a tighter crop or something to give the audience something to look at.', '2006-08-13 02:42:29.000000', NULL, 1),
(2721889, 374633, 60173, '<td valign="top">I think there''s a rule somewhere about feet and them not scoring well..</td>', 'I think there''s a rule somewhere about feet and them not scoring well..', '2006-08-13 02:42:52.000000', NULL, 1),
(2721909, 374860, 60173, '<td valign="top">While the idea is good the execution of it lacks.<br/> <br/>A few nit picks:<br/>The black is more of a brown than a black<br/>Lint and hairs on the base<br/>The whites look overexposed</td>', 'While the idea is good the execution of it lacks. A few nit picks:The black is more of a brown than a blackLint and hairs on the baseThe whites look overexposed', '2006-08-13 02:49:20.000000', NULL, 1),
(2721934, 374255, 60173, '<td valign="top">While the idea is pretty funny it doesn''t look like you tried very hard. A black sheet as a backdrop would have done wonders for this photo.</td>', 'While the idea is pretty funny it doesn''t look like you tried very hard. A black sheet as a backdrop would have done wonders for this photo.', '2006-08-13 02:58:06.000000', NULL, 1),
(2721943, 374433, 60173, '<td valign="top">The framing isn''t bad, but it being so overexposed hurts everything that the photo has going for it. There''s some very harsh reflections on the little boy.</td>', 'The framing isn''t bad, but it being so overexposed hurts everything that the photo has going for it. There''s some very harsh reflections on the little boy.', '2006-08-13 03:01:11.000000', NULL, 1),
(2721953, 373825, 60173, '<td valign="top">It would really add to it if someone/anyone were looking at the camera. Overall the photo is pretty overexposed, but the angle is nice. Good idea though.</td>', 'It would really add to it if someone/anyone were looking at the camera. Overall the photo is pretty overexposed, but the angle is nice. Good idea though.', '2006-08-13 03:05:05.000000', NULL, 1),
(2721962, 377548, 60173, '<td valign="top">Way too much sky and all the colors seem washed out.  =(</td>', 'Way too much sky and all the colors seem washed out.  =(', '2006-08-13 03:08:41.000000', NULL, 1),
(2721964, 377492, 60173, '<td valign="top">This is one of those ideas that has been done so many times that you have to do something pretty amazing to impress people with it. I wasn''t awed. Sorry.  =(</td>', 'This is one of those ideas that has been done so many times that you have to do something pretty amazing to impress people with it. I wasn''t awed. Sorry.  =(', '2006-08-13 03:11:07.000000', NULL, 1),
(2721972, 377164, 60173, '<td valign="top">You''re way overexposed in the background. A tighter crop on the boat to the right would have scored much better.</td>', 'You''re way overexposed in the background. A tighter crop on the boat to the right would have scored much better.', '2006-08-13 03:14:47.000000', NULL, 1),
(2721975, 376663, 60173, '<td valign="top">That''s a whole lot of blue. I would have suggested cropping out much of the dead space.</td>', 'That''s a whole lot of blue. I would have suggested cropping out much of the dead space.', '2006-08-13 03:16:51.000000', NULL, 1),
(2721981, 376528, 60173, '<td valign="top">I''m trying to figure out if this was taken indoors or outside. It looks like a museum exibit. If that is indeed what it is, I think it would look better if there were a way to make it look like it weren''t inside. Since it is such an old train you could make it black/white and give it that rustic color tint. That might also help pull it out of the museum and back out into the real world.  =)</td>', 'I''m trying to figure out if this was taken indoors or outside. It looks like a museum exibit. If that is indeed what it is, I think it would look better if there were a way to make it look like it weren''t inside. Since it is such an old train you could make it black/white and give it that rustic color tint. That might also help pull it out of the museum and back out into the real world.  =)', '2006-08-13 03:25:16.000000', NULL, 1),
(2721992, 376260, 60173, '<td valign="top">I copied this into Photoshop and through Hue/Saturation took out the yellow and green. I like it better without the grass, but my boyfriend likes it better with. I think it makes the colors from the kids stand out more. Something to play with anyway..</td>', 'I copied this into Photoshop and through Hue/Saturation took out the yellow and green. I like it better without the grass, but my boyfriend likes it better with. I think it makes the colors from the kids stand out more. Something to play with anyway..', '2006-08-13 03:38:00.000000', NULL, 1),
(2721996, 377314, 60173, '<td valign="top">Bumping the contrast up a little bit helps bring out that bright yellow we all know and love. (or hate, heh)</td>', 'Bumping the contrast up a little bit helps bring out that bright yellow we all know and love. (or hate, heh)', '2006-08-13 03:46:03.000000', NULL, 1),
(2721999, 377467, 60173, '<td valign="top">The lens flare really doesn''t work for me. Do you have a UV filter on that might be adding to the glare?</td>', 'The lens flare really doesn''t work for me. Do you have a UV filter on that might be adding to the glare?', '2006-08-13 03:52:26.000000', NULL, 1),
(2722001, 376693, 60173, '<td valign="top">Love the angle. Slightly out of focus though.</td>', 'Love the angle. Slightly out of focus though.', '2006-08-13 03:56:13.000000', NULL, 1),
(2722005, 374254, 60173, '<td valign="top">Seems a tad too dark, but very well composed.</td>', 'Seems a tad too dark, but very well composed.', '2006-08-13 04:10:24.000000', NULL, 1),
(2722009, 376371, 60173, '<td valign="top">That''s just silly!<br/> <br/>I played around with this a little in photoshop. I desaturated it and then did variations to add a orangey brown tint. I also bumped the sharpness to bring out his hairs more. It makes it look like an old circus photo, heh.</td>', 'That''s just silly! I played around with this a little in photoshop. I desaturated it and then did variations to add a orangey brown tint. I also bumped the sharpness to bring out his hairs more. It makes it look like an old circus photo, heh.', '2006-08-13 04:21:31.000000', NULL, 1),
(2722058, 377406, 58081, '<td valign="top">Those Glacier National Park bus drivers don''t pose their Jammer buses for you for nothing! I see Mt. Reynolds in the background (on the left), so this must be at Logan Pass. Considering the difficulty in set-up, it''s a nice shot.</td>', 'Those Glacier National Park bus drivers don''t pose their Jammer buses for you for nothing! I see Mt. Reynolds in the background (on the left), so this must be at Logan Pass. Considering the difficulty in set-up, it''s a nice shot.', '2006-08-13 06:02:41.000000', NULL, 1),
(2722062, 377327, 58081, '<td valign="top">Well done. One of my favorites.</td>', 'Well done. One of my favorites.', '2006-08-13 06:04:19.000000', NULL, 1),
(2722081, 374701, 58081, '<td valign="top">You really captured the moment. Very good!</td>', 'You really captured the moment. Very good!', '2006-08-13 06:26:05.000000', NULL, 1),
(2722094, 376514, 58081, '<td valign="top">You wore a blue shirt that day...Lots of reflections of the parking lot. Chrome is tough to shoot. I''ve had the best luck with a 200mm lens to eliminate my reflection. Good luck.</td>', 'You wore a blue shirt that day...Lots of reflections of the parking lot. Chrome is tough to shoot. I''ve had the best luck with a 200mm lens to eliminate my reflection. Good luck.', '2006-08-13 06:44:30.000000', NULL, 1),
(2722095, 375817, 58081, '<td valign="top">Nice color contrast and good use of negative space on the right side of the photo.</td>', 'Nice color contrast and good use of negative space on the right side of the photo.', '2006-08-13 06:46:42.000000', NULL, 1),
(2722179, 377114, 24983, '<td valign="top">cool shot mate</td>', 'cool shot mate', '2006-08-13 09:46:27.000000', NULL, 1),
(2722183, 375034, 27524, '<td valign="top">Nice reflection on water, like the dark bacground but ovel all it lacks some clearness and bit moor contrast.</td>', 'Nice reflection on water, like the dark bacground but ovel all it lacks some clearness and bit moor contrast.', '2006-08-13 09:48:55.000000', NULL, 1),
(2722186, 374716, 27524, '<td valign="top">Pretty interesting angle and composition, though sun makes it pretty overexposed. Also feels like there could be bit more focus.</td>', 'Pretty interesting angle and composition, though sun makes it pretty overexposed. Also feels like there could be bit more focus.', '2006-08-13 09:50:58.000000', NULL, 1),
(2722189, 376693, 27524, '<td valign="top">Its very interesting object and nice picture but it misses some real point of interest. Maybe i would try it at another weather with some dramatic stormy sky.</td>', 'Its very interesting object and nice picture but it misses some real point of interest. Maybe i would try it at another weather with some dramatic stormy sky.', '2006-08-13 09:54:05.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
