(2724932, 376718, 33515, '<td valign="top">What a great photograph for this challenge. It seems the bike could be in better focus, but I love this one. 10</td>', 'What a great photograph for this challenge. It seems the bike could be in better focus, but I love this one. 10', '2006-08-14 09:22:10.000000', NULL, 1),
(2724934, 377586, 33515, '<td valign="top">I gave this a 10, I can''t put my finger on what I like, but it is a solid photograph. Well done, best of luck.</td>', 'I gave this a 10, I can''t put my finger on what I like, but it is a solid photograph. Well done, best of luck.', '2006-08-14 09:22:13.000000', NULL, 1),
(2724938, 375817, 32378, '<td valign="top">This shows transportation nicely.  However, I think some fill flash here would have helped bring the babies and his face out better.</td>', 'This shows transportation nicely.  However, I think some fill flash here would have helped bring the babies and his face out better.', '2006-08-14 09:23:10.000000', NULL, 1),
(2724941, 377546, 32378, '<td valign="top">I like the coupe, only thing that doesn''t tie into this picture is the chevy sign in the back ground.</td>', 'I like the coupe, only thing that doesn''t tie into this picture is the chevy sign in the back ground.', '2006-08-14 09:25:17.000000', NULL, 1),
(2724942, 375848, 29462, '<td valign="top">I love the balance of this shot 10</td>', 'I love the balance of this shot 10', '2006-08-14 09:25:54.000000', NULL, 1),
(2724944, 377114, 33515, '<td valign="top">I like this photo, but I wonder what the dog is looking for. It seems to me to be cropped in a little tight and maybe if the angle was more from the back looking in the same direction as the dog. On the other hand this is very whimsical and was a pleasant surprise when I opened it. 9</td>', 'I like this photo, but I wonder what the dog is looking for. It seems to me to be cropped in a little tight and maybe if the angle was more from the back looking in the same direction as the dog. On the other hand this is very whimsical and was a pleasant surprise when I opened it. 9', '2006-08-14 09:26:33.000000', NULL, 1),
(2724945, 374715, 32378, '<td valign="top">Not sure what the trasnportation is on this.  Perhaps the wind?  I like the overall effect of the picture though.  Too bad you couldn''t clone out the spots.</td>', 'Not sure what the trasnportation is on this.  Perhaps the wind?  I like the overall effect of the picture though.  Too bad you couldn''t clone out the spots.', '2006-08-14 09:26:56.000000', NULL, 1),
(2724947, 375368, 32378, '<td valign="top">Good composition, I like the way the tire track leads you to the bike.</td>', 'Good composition, I like the way the tire track leads you to the bike.', '2006-08-14 09:27:39.000000', NULL, 1),
