(2725019, 376701, 63977, '<td valign="top">I love the angle in this shot and the movement of the train is great</td>', 'I love the angle in this shot and the movement of the train is great', '2006-08-14 09:56:43.000000', NULL, 1),
(2725024, 376951, 62554, '<td valign="top">Beautiful capture .. no over blown hilites, great clarity and sharpness and full of colour.  Excellent!</td>', 'Beautiful capture .. no over blown hilites, great clarity and sharpness and full of colour.  Excellent!', '2006-08-14 09:57:45.000000', NULL, 1),
