(2725501, 374433, 16004, '<td valign="top">nice family photo; the colours and lighting are a bit harsh though - kind of have rpreconceived ideas that a fire engine should be red, and this looks mostly orange.  it''s also not really within the realms of transportation, to be honest.  it''s a fun photo, but not really arty farty enough for dpc i''m afraid.  4.</td>', 'nice family photo; the colours and lighting are a bit harsh though - kind of have rpreconceived ideas that a fire engine should be red, and this looks mostly orange.  it''s also not really within the realms of transportation, to be honest.  it''s a fun photo, but not really arty farty enough for dpc i''m afraid.  4.', '2006-08-14 12:10:07.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2725545, 377295, 41008, '<td valign="top">YEAH!</td>', 'YEAH!', '2006-08-14 12:25:07.000000', NULL, 1),
(2725551, 375571, 41008, '<td valign="top">IMPALA!!!! Yes! Ah, I would recognize those tail-lights anywhere.</td>', 'IMPALA!!!! Yes! Ah, I would recognize those tail-lights anywhere.', '2006-08-14 12:26:46.000000', NULL, 1),
(2725559, 376656, 41008, '<td valign="top">This ought to ribbon... glorious!</td>', 'This ought to ribbon... glorious!', '2006-08-14 12:29:42.000000', NULL, 1),
(2725582, 376529, 16004, '<td valign="top">when i voted, i gave this a 4.  though there are aspects i liked, i felt the discolouration and fringing in the sky and on the near wing to be excessive.  the smoggy haze, the brownness of the runway, and the look of the other aircraft in terms of angle, lighting, feel, are all really good.  it''s the sky, plus that really bright reflection on the tail, that lets you down.</td>', 'when i voted, i gave this a 4.  though there are aspects i liked, i felt the discolouration and fringing in the sky and on the near wing to be excessive.  the smoggy haze, the brownness of the runway, and the look of the other aircraft in terms of angle, lighting, feel, are all really good.  it''s the sky, plus that really bright reflection on the tail, that lets you down.', '2006-08-14 12:40:40.000000', NULL, 1),
(2725603, 376514, 16004, '<td valign="top">i only voted this a 4, i''m afraid.  i just didn''t connect with the shot in any sort of way...  i think more of the car than just the grille might have proved more wow, because, and let''s face it, the hummer is a silly looking car and a picture showing how silly might be more fun than this almost too modestly sensible look at it.  plus, i thought there was too much going on reflected in the chrome (not including the half a dozen versions of you!).  if it was parked closer to the beach, and only sky and sand and sea was reflected, i think that might be more effective.  just my thoughts, really.</td>', 'i only voted this a 4, i''m afraid.  i just didn''t connect with the shot in any sort of way...  i think more of the car than just the grille might have proved more wow, because, and let''s face it, the hummer is a silly looking car and a picture showing how silly might be more fun than this almost too modestly sensible look at it.  plus, i thought there was too much going on reflected in the chrome (not including the half a dozen versions of you!).  if it was parked closer to the beach, and only sky and sand and sea was reflected, i think that might be more effective.  just my thoughts, really.', '2006-08-14 12:46:46.000000', NULL, 1),
(2725890, 376551, 16004, '<td valign="top">wow!  from the thumbnail this looked so unpromising, but at full size it''s remarkably brilliant.  i love the slightly bonkers sense of scale, and how in focus the fat plane is compared to the rest of the stuff in the picture.  this photo is so rich in style.  i think it could do with a bit of a border, though, and i kind of wish that the red things in the foreground weren''t there (or at least, not be red).  but this is a really striking and enjoyable image.  9.</td>', 'wow!  from the thumbnail this looked so unpromising, but at full size it''s remarkably brilliant.  i love the slightly bonkers sense of scale, and how in focus the fat plane is compared to the rest of the stuff in the picture.  this photo is so rich in style.  i think it could do with a bit of a border, though, and i kind of wish that the red things in the foreground weren''t there (or at least, not be red).  but this is a really striking and enjoyable image.  9.', '2006-08-14 15:30:33.000000', NULL, 1),
(2725902, 377387, 16004, '<td valign="top">a great shot.  great sense of scale, gorgeous bright colours, lovely clarity and level of detail.  i love how the front end is about to plummet out of the frame of the photo.  can''t really fault this picture, so have no cause to give it anything other than a 10.</td>', 'a great shot.  great sense of scale, gorgeous bright colours, lovely clarity and level of detail.  i love how the front end is about to plummet out of the frame of the photo.  can''t really fault this picture, so have no cause to give it anything other than a 10.', '2006-08-14 15:32:37.000000', NULL, 1),
(2725916, 377235, 16004, '<td valign="top">nice city scene; seems like an incredibly photogenic place.  i don''t really feel that the boat fills enough of the frame to really be for this particular challenge, and also my attention is being theifed by those two towers on the right.  the bright sky is also somewhat overpowering; it might have been nifty to keep it the same width and crop the top half to two thirds out, and then add thick black borders top and bottom.  it would make it quite panoramic,get rid of the bright sunny haze and draw attention back to the boat and the lovely green water.  6.</td>', 'nice city scene; seems like an incredibly photogenic place.  i don''t really feel that the boat fills enough of the frame to really be for this particular challenge, and also my attention is being theifed by those two towers on the right.  the bright sky is also somewhat overpowering; it might have been nifty to keep it the same width and crop the top half to two thirds out, and then add thick black borders top and bottom.  it would make it quite panoramic,get rid of the bright sunny haze and draw attention back to the boat and the lovely green water.  6.', '2006-08-14 15:37:25.000000', NULL, 1),
(2725925, 376485, 16004, '<td valign="top">too dark and not really directed to anything in particular, just bits of train.  too messy, and i''m left wanting to see the bigger picture.  3.</td>', 'too dark and not really directed to anything in particular, just bits of train.  too messy, and i''m left wanting to see the bigger picture.  3.', '2006-08-14 15:40:16.000000', NULL, 1),
(2725963, 377571, 50935, '<td valign="top">awesome feeling to this...  9.</td>', 'awesome feeling to this...  9.', '2006-08-14 15:56:02.000000', NULL, 1),
